void printTree(JsonNode node, String prefix) {
    if (node.isObject()) {
        node.fields().forEachRemaining(e -> {
            System.out.println(prefix + e.getKey() + ":");
            printTree(e.getValue(), prefix + "  ");
        });
    } else if (node.isArray()) {
        for (JsonNode el : node) printTree(el, prefix + "- ");
    } else {
        System.out.println(prefix + node.asText());
    }
}

