Map<String,Object[]> diff(Person a, Person b) {
    ObjectNode na = mapper.valueToTree(a);
    ObjectNode nb = mapper.valueToTree(b);
    Map<String,Object[]> roznice = new LinkedHashMap<>();
    na.fieldNames().forEachRemaining(f -> {
        if (!na.get(f).equals(nb.get(f))) {
            roznice.put(f, new Object[]{na.get(f), nb.get(f)});
        }
    });
    return roznice;
}

